 @page "/settings"
 @rendermode InteractiveServer
 @inject CascadingValueSource<ThemeInfo> ThemeSource

 <PageTitle>Settings</PageTitle>

 <h1>User Preferences</h1>

 <div class="card mt-4" style="max-width: 480px;">
     <div class="card-body">
         <h5 class="card-title">Theme</h5>

         <div class="btn-group mb-3" role="group">
             @foreach (var t in Enum.GetValues<Theme>())
             {
                 var active = t == CurrentTheme?.Theme ? "active" : "";
                 <button class="btn btn-outline-primary @active"
                         @onclick="() => SetTheme(t)">
                     @t
                 </button>
             }
         </div>

         <h5 class="card-title">Accent Color</h5>

         <div class="d-flex align-items-center gap-3 mb-3">
             <input type="color"
                    class="form-control form-control-color"
                    value="@CurrentTheme?.AccentColor"
                    @onchange="OnAccentChanged" />
             <span>@CurrentTheme?.AccentColor</span>
         </div>

         <div class="mt-3 p-3 rounded"
              style="background-color: @CurrentTheme?.AccentColor; color: white;">
             Preview: accent swatch
         </div>
     </div>
 </div>

 @code {
     [CascadingParameter]
     private ThemeInfo? CurrentTheme { get; set; }

     private async Task SetTheme(Theme theme)
     {
         var updated = new ThemeInfo
         {
             Theme = theme,
             AccentColor = CurrentTheme?.AccentColor ?? "#0d6efd"
         };
         await ThemeSource.NotifyChangedAsync(updated);
     }

     private async Task OnAccentChanged(ChangeEventArgs e)
     {
         var updated = new ThemeInfo
         {
             Theme = CurrentTheme?.Theme ?? Theme.Light,
             AccentColor = e.Value?.ToString() ?? "#0d6efd"
         };
         await ThemeSource.NotifyChangedAsync(updated);
     }
 }

